def neigh(a,b,eps):
 L=len(a); A=sum(x==y for x,y in zip(a,b)); S=0
 for x,y in zip(a,b):
  d=abs(x-y)
  if (x<1514<y) or (y<1514<x): d+=1000
  S+=d*d
 p,q=eps
 return S*9**A*q*q <= p*p*L*25**A

def brute(frags,eps,ratio):
 bylen={}
 for f in frags:bylen.setdefault(f.length,[]).append(f)
 m=len(frags); dens=max(2,(m*ratio[0]+ratio[1]-1)//ratio[1])
 clusters={}; noise=set()
 for L,fs in bylen.items():
  n=len(fs)
  adj=[[neigh(fs[i].values,fs[j].values,eps) for j in range(n)] for i in range(n)]
  deg=[sum(row) for row in adj]; core=[deg[i]>=dens for i in range(n)]
  seen=[False]*n
  comps=[]
  for s in range(n):
   if core[s] and not seen[s]:
    stack=[s]; seen[s]=True; comp=[]
    while stack:
     i=stack.pop();comp.append(i)
     for j in range(n):
      if core[j] and not seen[j] and adj[i][j]:seen[j]=True;stack.append(j)
    comps.append(comp)
  comps.sort(key=lambda inds:min(fs[i].fid for i in inds))
  for ins in comps:
   cid=min(fs[i].fid for i in ins); clusters[cid]={'core':sorted(fs[i].fid for i in ins),'members':set(fs[i].fid for i in ins)}
  for i in range(n):
   if core[i]:continue
   cand=[]
   for ci,ins in enumerate(comps):
    if any(adj[i][j] for j in ins):
     cand.append(min(fs[j].fid for j in ins))
   if cand:
    cid=min(cand);clusters[cid]['members'].add(fs[i].fid)
   else:noise.add(fs[i].fid)
 return {cid:(v['core'],sorted(v['members'])) for cid,v in clusters.items()},noise

